/* ---------------- sound (Web Audio, synthesized) ---------------- */
let AC=null, masterGain=null, muted=false;
function initAudio(){
  if(AC){if(AC.state==='suspended')AC.resume();return;}
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    masterGain=AC.createGain(); masterGain.gain.value=0.35;
    masterGain.connect(AC.destination);
  }catch(e){}
}
function tone(f0,f1,dur,type,vol,delay){
  if(!AC||muted)return;
  const t=AC.currentTime+(delay||0);
  const o=AC.createOscillator(),g=AC.createGain();
  o.type=type;
  o.frequency.setValueAtTime(Math.max(20,f0),t);
  o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
  g.gain.setValueAtTime(vol,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g);g.connect(masterGain);
  o.start(t);o.stop(t+dur+0.02);
}
let noiseBuf=null;
function getNoise(){
  if(!noiseBuf){
    noiseBuf=AC.createBuffer(1,AC.sampleRate*0.6,AC.sampleRate);
    const d=noiseBuf.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
  }
  return noiseBuf;
}
function noiseSnd(dur,vol,freq,delay){
  if(!AC||muted)return;
  const t=AC.currentTime+(delay||0);
  const s=AC.createBufferSource();s.buffer=getNoise();s.loop=true;
  const f=AC.createBiquadFilter();f.type='lowpass';
  f.frequency.setValueAtTime(freq,t);
  f.frequency.exponentialRampToValueAtTime(120,t+dur);
  const g=AC.createGain();
  g.gain.setValueAtTime(vol,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(masterGain);
  s.start(t);s.stop(t+dur+0.02);
}
