/* tractor beam: continuous sweeping sawtooth */
let beamNodes=null;
function beamStart(){
  if(!AC||muted||beamNodes)return;
  const o=AC.createOscillator(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();
