function setupStage(stage){
  G.enemies=[];G.pshots=[];G.ebullets=[];G.captive=null;G.beamBoss=null;
  beamStop();
  G.entry={t:0,done:false};G.entryDone=false;G.fclock=0;
  G.diveTimer=200-stage*8;
  for(const grp of ENTRY_ORDER){
    let d=grp.delay;
    for(const m of grp.members){
      const e=makeEnemy(m[0],m[1],m[2]);
      e.path=ENTRY_PATHS[grp.path]; e.pathT=-d; d+=7;
      G.enemies.push(e);
    }
