}
function stageNumber(n){return ((n-1)%4)+1;}
function isChallenge(n){return n>=3&&((n-3)%4)===0;}

/* ---------------- dive logic ---------------- */
function canDive(){
  return G.entryDone&&!G.beamBoss&&!G.captive||
        (G.captive&&G.captive.boss&&G.captive.boss.state==='formation');
}
function beginDive(e){
  const sp=slotPos(e);
  e.x=sp[0];e.y=sp[1];
  const px=G.player&&G.player.state==='play'?G.player.x:W/2;
  const dir=px>sp[0]?1:-1;
  const wob=rnd(20,60)*dir;
  const speed=0.009+0.0009*Math.min(stageNumber(G.stage),10);
  e.state='diving';e.t=0;e.shot=0;
  e.dive={speed,
    p1:[sp[0],sp[1]],[
    ]};
  e.dive.p1=[sp[0],sp[1]];
  e.dive.p2=[sp[0]+dir*rnd(25,45),sp[1]+rnd(25,45)];
  e.dive.p3=[px+wob,rnd(120,180)];
  e.dive.p4=[px+rnd(-15,15),H+20];
}
function pickDiver(){
  const pool=G.enemies.filter(e=>e.state==='formation');
  if(!pool.length)return;
  const bosses=pool.filter(e=>e.type==='boss');
  const doBeam=bosses.length&&stageNumber(G.stage)>=2&&Math.random()<Math.min(0.45,0.12+0.05*stageNumber(G.stage));
  if(doBeam){
    const b=bosses[(Math.random()*bosses.length)|0];
    startBeamDive(b);
    return;
  }
  /* boss dive with escorts */
  if(bosses.length&&Math.random()<0.25){
    const b=bosses[(Math.random()*bosses.length)|0];
    const esc=pool.filter(e=>e.type==='goei').sort(()=>Math.random()-0.5).slice(0,2);
    beginDive(b);
    esc.forEach((s,i)=>{s.state='escort';s.escortOf=b;});
    return;
  }
  const e=pool[(Math.random()*pool.length)|0];
  beginDive(e);
}
function startBeamDive(b){
  const sp=slotPos(b);
  b.x=sp[0];b.y=sp[1];
  const px=G.player?G.player.x:W/2;
  b.state='beamdive';b.t=0;
  b.beam={tx:clamp(px,50,W-50),ty:140,phase:0,timer:0};
  if(G.captive){G.captive.state='held';}
}
function reenter(e){
  const sp=slotPos(e);
  e.state='reenter';e.t=0;
  e.d2={p1:[e.x,-16],p2:[e.x,40],p3:[sp[0]+(e.x>sp[0]?60:-60),sp[1]+30],p4:[sp[0],sp[1]]};
}

/* ---------------- update: enemies ---------------- */
function updateEnemies(){
  let allIn=true;
  for(const e of G.enemies){
    e.flap++;
    if(e.state==='wait'){
      if(e.pathT<0)e.pathT+=1;
      else {e.state='entering';e.pathT=0;}
    }
    if(e.state==='entering'){
      allIn=false;
      e.pathT+=0.0055;
      const p=pathPos(e.path,clamp(e.pathT,0,1));
      e.x=p[0];e.y=p[1];
      /* enemies may fire while entering */
      if(e.y>40&&e.y<200&&Math.random()<0.0012+G.stage*0.0002)enemyShoot(e);
      if(e.pathT>=1)e.state='toslot';
    }else if(e.state==='toslot'){
      allIn=false;
      const sp=slotPos(e);
      const d=dist(e.x,e.y,sp[0],sp[1]);
      if(d<2.5){e.state='formation';e.x=sp[0];e.y=sp[1];}
      else{e.x+=(sp[0]-e.x)/d*3;e.y+=(sp[1]-e.y)/d*3;}
    }else if(e.state==='formation'){
      const sp=slotPos(e);e.x=sp[0];e.y=sp[1];
    }else if(e.state==='diving'){
      e.t+=e.dive.speed*(1+0.08*Math.min(stageNumber(G.stage),10));
      const d=e.dive;
      const p=cubic(d.p1,d.p2,d.p3,d.p4,clamp(e.t,0,1));
      e.x=p[0];e.y=p[1];
      e.shot--;
      if(e.shot<=0&&e.y>60&&e.y<200&&G.player&&G.player.state==='play'){
        enemyShoot(e);e.shot=Math.floor(rnd(25,60));
      }
      if(e.t>=1){e.y=-16;reenter(e);}
    }else if(e.state==='escort'){
      /* escorts stay glued near their boss */
      const b=e.escortOf;
      if(!b||b.hp<=0||(b.state!=='diving'&&b.state!=='beamdive')){beginDive(e);}
      else{
        const i=e.escIdx||(e.escIdx=(e.seed>0.5?1:2));
        e.x=b.x+(i===1?-16:16);e.y=b.y+8;
        e.shot--;
        if(e.shot<=0&&b.y>60&&G.player&&G.player.state==='play'){enemyShoot(e);e.shot=Math.floor(rnd(40,80));}
        if(b.state==='beamdive'&&b.beam.phase===3){/* beam boss returns: escort follows reentry */
          if(!e._re){e._re=1;reenter(e);}
        }
      }
    }else if(e.state==='beamdive'){
      const bm=e.beam;
      if(bm.phase===0){ /* descend to hover point */
        bm.d=(bm.d||0)+0.012;
        if(!bm.p1){
          bm.p1=[e.x,e.y];bm.p2=[e.x,e.y+30];bm.p3=[bm.tx-10,bm.ty-30];bm.p4=[bm.tx,bm.ty];
        }
        const p=cubic(bm.p1,bm.p2,bm.p3,bm.p4,clamp(bm.d,0,1));
        e.x=p[0];e.y=p[1];
        if(bm.d>=1){bm.phase=1;bm.timer=0;beamStart();
          if(G.captive)G.captive.state='following';}
      }else if(bm.phase===1){ /* beam open */
        bm.timer++;
        if(bm.timer>45)bm.phase=2;
      }else if(bm.phase===2){ /* beam closing */
        bm.timer++;
        if(bm.timer>140){bm.phase=3;bm.timer=0;beamStop();}
      }else{ /* return to formation */
        const sp=slotPos(e);
        e.x+=(sp[0]-e.x)*0.03;e.y+=(sp[1]-e.y)*0.03;
        if(dist(e.x,e.y,sp[0],sp[1])<2){
          e.state='formation';e.beam=null;
          if(G.captive)G.captive.state='held';
        }
      }
      if(G.captive&&G.captive.state==='following'){
        G.captive.x=e.x;G.captive.y=e.y-16;
        G.captive.shot=(G.captive.shot||0)-1;
        if(G.captive.shot<=0&&e.y>80&&G.player&&G.player.state==='play'){
          enemyShoot(G.captive);G.captive.shot=70;
        }
      }
    }else if(e.state==='reenter'){
      e.t+=0.014;
      const d=e.d2;
      const p=cubic(d.p1,d.p2,d.p3,d.p4,clamp(e.t,0,1));
      e.x=p[0];e.y=p[1];
      if(e.t>=1)e.state='formation';
    }else if(e.state==='challenge'){
      e.pathT+=0.0052;
      const p=pathPos(e.path,clamp(e.pathT,0,1));
      e.x=p[0];e.y=p[1];
      if(e.pathT>=1){e.dead=true;} /* flies away, does not stay */
    }
  }
  if(!G.entryDone&&allIn&&!G.enemies.some(e=>e.state==='wait'||e.state==='entering'||e.state==='toslot')){
    G.entryDone=true;
  }
}
function enemyShoot(o){
  const dx=(G.player?G.player.x:o.x)-o.x, dy=(G.player?G.player.y:o.y)-o.y;
  const d=Math.hypot(dx,dy)||1;
  const sp=1.3+0.05*Math.min(stageNumber(G.stage),10);
  G.ebullets.push({x:o.x,y:o.y+5,vx:dx/d*sp,vy:dy/d*sp,w:3,h:4});
}

/* ---------------- update: player ---------------- */
function updatePlayer(){
  const p=G.player;
  if(!p)return;
  if(p.state==='ready'){
    p.timer--;
    if(p.timer<=0)p.state='play';
    return;
  }
  if(p.state==='capture'){ /* being pulled up by beam */
    p.capture.t++;
    const b=G.beamBoss, k=p.capture.t/70;
    p.x=p.capture.sx+(b.x-p.capture.sx)*k;
    p.y=p.capture.sy+(b.y+12-p.capture.sy)*k;
    if(p.capture.t>=70){
      /* ship becomes the captive */
      G.captive={x:b.x,y:b.y-16,boss:b,state:'held',w:11,h:11,shot:999};
      p.capture.dead=true;
      loseLife(false);
    }
    return;
  }
  if(p.state!=='play')return;
  const L=keys['arrowleft']||keys['a'], R=keys['arrowright']||keys['d'];
  if(L)p.x-=2.4;
  if(R)p.x+=2.4;
  p.x=clamp(p.x,12,W-12);
  if(p.fireCd>0)p.fireCd--;
  if(keys[' ']&&p.fireCd<=0&&G.pshots.length<2){
    if(p.dual){
      G.pshots.push({x:p.x-9,y:p.y-8,vx:0,vy:-7,w:3,h:8});
      G.pshots.push({x:p.x+9,y:p.y-8,vx:0,vy:-7,w:3,h:8});
      G.shotsFired+=2;
    }else{
      G.pshots.push({x:p.x,y:p.y-8,vx:0,vy:-7,w:3,h:8});
      G.shotsFired++;
    }
    p.fireCd=13;sShot();
  }
}
function loseLife(wasCaptured){
  const p=G.player;
  beamStop();
  if(p&&p.state==='capture')p.capture.dead=true;
  G.lives--;
  if(!wasCaptured)boom(p.x,p.y,'player');
  sPlayerDie();
  if(G.lives>0){
    p.state='dead';p.timer=110;
    showMsg('READY',100);
  }else{
    p.state='dead';p.timer=140;
    G.overTimer=170;
  }
}
function respawnIfDue(){
  const p=G.player;
  if(p&&p.state==='dead'){
    p.timer--;
    if(p.timer<=0){
      G.player=makePlayer();
      showMsg('READY',100);
    }
  }
}

/* ---------------- update: shots & collisions ---------------- */
function killEnemy(e,byPlayer){
  e.dead=true;
  boom(e.x,e.y,'enemy');
  if(e.type==='boss'){
    sBossDie();
    if(G.captive&&G.captive.boss===e){
      boom(G.captive.x,G.captive.y,'player');
      G.captive=null;
      if(e.state==='formation')sRescue(); /* captive lost */
    }
  }else if(e.type==='goei')sGoeiHit();
  else sZakoHit();
}
function updateShots(){
  const p=G.player;
  /* player shots */
  for(const s of G.pshots){
    s.x+=s.vx;s.y+=s.vy;
    if(s.y<-10||s.y>H+10){s.dead=true;continue;}
    for(const e of G.enemies){
      if(e.dead||e.state==='wait')continue;
      if(e.state==='entering'&&e.pathT<0.05)continue;
      if(aabb(s,enemyHitbox(e))){
        s.dead=true;G.shotsHit++;
        if(e.type==='boss'&&e.hp===2){
          e.hp=1;sBossHit1();
          /* rescue: captive's boss shot while diving -> free the fighter */
          if(G.captive&&G.captive.boss===e&&(e.state==='diving'||e.state==='beamdive')){
            beamStop();
            const c=G.captive;G.captive=null;
            c.state='freed';c.vy=1.4;c.t=0;
            G.captiveFreed=c;
            sRescue();
          }
        }else{
          addScore(scoreFor(e));
          killEnemy(e,true);
        }
        break;
      }
    }
  }
  /* freed fighter descends and docks */
  if(G.captiveFreed){
    const c=G.captiveFreed;
    c.y+=c.vy;
    if(p&&p.state==='play'){
      c.x+=(p.x-c.x)*0.08;
      if(c.y>=p.y-14){
        G.captiveFreed=null;
        if(!p.dual){p.dual=true;sDock();}
      }
    }else c.y+=0.5;
    if(c&&c.y>H+20)G.captiveFreed=null;
  }
  /* enemy bullets */
  for(const b of G.ebullets){
    b.x+=b.vx;b.y+=b.vy;
    if(b.y>H+10||b.y<-10||b.x<-10||b.x>W+10){b.dead=true;continue;}
    if(p&&p.state==='play'){
      for(const half of playerHalves(p)){
        if(aabb(b,{x:half.x,y:half.y,w:half.w-2,h:half.h-2})){
          b.dead;
          b.dead=true;
          if(p.dual&&half.side!==0){
            /* only that half is lost */
            p.dual=false;
            boom(half.x,p.y,'player');
            sPlayerDie();
            G.lives--;
            if(G.lives<=0){p.state='dead';p.timer=140;G.overTimer=170;beamStop();}
          }else{
            loseLife(false);
          }
          break;
        }
      }
    }
  }
  /* enemy <-> player body collisions */
  if(p&&p.state==='play'){
    for(const e of G.enemies){
      if(e.dead||e.state==='wait'||e.state==='formation')continue;
      if(e.state==='entering'&&e.pathT<0.05)continue;
      for(const half of playerHalves(p)){
        if(aabb(enemyHitbox(e),{x:half.x,y:half.y,w:half.w-2,h:half.h-2})){
          addScore(scoreFor(e));
          killEnemy(e,false);
          if(p.dual&&half.side!==0){
            p.dual=false;boom(half.x,p.y,'player');sPlayerDie();
            G.lives--;
            if(G.lives<=0){p.state='dead';p.timer=140;G.overTimer=170;beamStop();}
          }else{
            loseLife(false);
          }
          break;
        }
      }
      if(p.state!=='play')break;
    }
  }
  /* tractor beam capture check */
  if(p&&p.state==='play'&&G.beamBoss&&G.beamBoss.beam&&G.beamBoss.beam.phase>=1&&!G.captive){
    const b=G.beamBoss, bm=b.beam;
    const grow=bm.phase===1?Math.min(1,bm.timer/45):Math.max(0,1-(bm.timer-45)/95);
    const halfMax=30*grow;
    const cy=b.y+10;
    if(p.y>cy&&p.y<H-8){
      const half=halfMax*((p.y-cy)/(H-8-cy));
      if(Math.abs(p.x-b.x)<half*0.85){
        /* captured! */
        p.state='capture';
        p.capture={t:0,sx:p.x,sy:p.y};
        G.beamBoss=b;
        sCapture();
      }
    }
  }
  /* track beam boss reference */
  G.beamBoss=G.enemies.find(e=>e.state==='beamdive')||null;
}

/* ---------------- main update ---------------- */
function update(){
  G.frame++;G.t+=STEP;
  updateStars();
  if(G.msgTimer>0)G.msgTimer--;
  if(G.state==='attract'){
    G.fclock++;
    if(G.frame%150===0)G.attractDemo=(G.attractDemo+1)%3;
    return;
  }
  if(G.state==='stageintro'){
    G.fclock++;
    if(G.msgTimer<=0){
      if(isChallenge(G.stage)){G.state='chintro';G.msgTimer=120;}
      else{G.state='play';sJingle();}
    }
    return;
  }
  if(G.state==='chintro'){
    if(G.msgTimer<=0){
      G.state='play';G.chWave=0;G.chHits=0;G.chWaveDelay=30;
      G.enemies=[];
      sJingle();
    }
    return;
  }
  if(G.state==='choutro'){
    if(G.msgTimer<=0){G.stage++;G.state='stageintro';G.msgTimer=130;setupStage(G.stage);}
    return;
  }
  if(G.state==='over'){
    if(G.msgTimer<=0){G.state='attract';}
    return;
  }
  if(G.state!=='play'||G.paused)return;

  G.fclock++;
  if(G.entry)G.entry.t++;
  updateEnemies();
  updatePlayer();
  respawnIfDue();
  updateShots();
  for(const s of G.pshots)if(s.dead)G.pshots.splice(G.pshots.indexOf(s),1);
  for(const b of G.ebullets)if(b.dead)G.ebullets.splice(G.ebullets.indexOf(b),1);
  for(const e of G.enemies)if(e.dead)G.enemies.splice(G.enemies.indexOf(e),1);
  for(const x of G.explosions){x.t++;if(x.t>24)G.explosions.splice(G.explosions.indexOf(x),1);}

  if(isChallenge(G.stage)){
    /* challenge stage waves */
    if(G.chWave<5){
      if(G.enemies.length===0){
        if(G.chWaveDelay>0){
          G.chWaveDelay--;
        }else{
          spawnChallengeWave();
          G.chWave++;
          sWave();
        }
      }
    }else if(G.enemies.length===0){
      /* tally bonuses */
      let bonus=0;
      if(G.chHits>=40){bonus=10000;addScore(10000);sBonus();}
      const perfect=G.chHits>=40;
      showMsg('NUMBER OF HITS: '+G.chHits+(perfect?'  PERFECT!':''),170);
      G.state='choutro';G.msgTimer=170;
    }
  }else{
    /* dive scheduling */
    if(G.entryDone&&G.player&&G.player.state==='play'){
      G.diveTimer--;
      if(G.diveTimer<=0){
        pickDiver();
        const s=stageNumber(G.stage);
        G.diveTimer=Math.max(35,150-s*12)+rnd(0,60);
      }
    }
    /* stage cleared? */
    if(G.entryDone&&G.enemies.length===0&&(!G.player||G.player.state!=='capture')){
      G.stage++;
      G.state='stageintro';G.msgTimer=130;
      setupStage(G.stage);
      beamStop();
    }
  }
  /* game over */
  if(G.player&&G.player.state==='dead'&&G.lives<=0){
    G.overTimer--;
    if(G.overTimer<=0&&G.msg!=='GAME OVER'){
      showMsg('GAME OVER',150);
      G.state='over';G.msgTimer=150;
      beamStop();
    }
  }
}

/* ---------------- rendering ---------------- */
function txt(s,x,y,col,size,align){
  ctx.fillStyle=col||'#fff';
  ctx.font='bold '+(size||8)+'px monospace';
  ctx.textAlign=align||'left';
  ctx.fillText(s,x,y);
  ctx.textAlign='left';
}
function drawFlag(x,y,label,col){
  ctx.fillStyle='#fff';ctx.fillRect(x,y,1,9);
  ctx.fillStyle=col;
  ctx.beginPath();
  ctx.moveTo(x+1,y);ctx.lineTo(x+8,y+2);ctx.lineTo(x+1,y+4);ctx.closePath();ctx.fill();
  txt(label,x+5,y+9,'#fff',6,'center');
}
function drawBadges(n){
  /* arcade denominations: 50,30,20,10,5,1 flags */
  const den=[[50,'#ff3333'],[30,'#33ccff'],[20,'#ffcc33'],[10,'#33ff66'],[5,'#ff66ff'],[1,'#ffffff']];
  let x=W-6;const y=H-16;
  let rem=n;
  for(const [d,c] of den){
    while(rem>=d){drawFlag(x-8,y,''+d,c);x-=12;rem-=d;}
  }
}
function drawHUD(){
  txt('1UP',8,11,'#33ccff');
  txt(String(G.score).padStart(6,' '),48,11,'#fff');
  txt('HIGH SCORE',128,11,'#ff3333');
  txt(String(highScore).padStart(6,' '),196,11,'#fff',8,'right');
  /* reserve ships */
  for(let i=0;i<Math.max(0,G.lives-1);i++)ctx.drawImage(FIGHTER,8+i*16,H-14);
  drawBadges(G.stage);
}
function drawBeam(b){
  const bm=b.beam;
  const grow=bm.phase===1?Math.min(1,bm.timer/45):bm.phase===2?Math.max(0,1-(bm.timer-45)/95):0;
  if(bm.phase<1||grow<=0)return;
  const top=b.y+10, bot=H-8;
  const half=30*grow;
  const cols=['#2244ff','#3366ff','#55aaff','#88ccff','#ffffff'];
  for(let y=top;y<bot;y+=2){
    const f=(y-top)/(bot-top);
    const hw=half*f;
    const stripe=Math.floor((y-G.t*3)/4)%cols.length;
    ctx.globalAlpha=0.55;
    ctx.fillStyle=cols[(stripe+4)%cols.length];
    ctx.fillRect(b.x-hw,y,hw*2,2);
  }
  ctx.globalAlpha=1;
}
function drawPlayer(){
  const p=G.player;
  if(!p||p.state==='dead')return;
  const spr=p.state==='capture'?FIGHTER_CAP:FIGHTER;
  if(p.dual){
    ctx.drawImage(FIGHTER,p.x-9-7,p.y-6);
    ctx.drawImage(FIGHTER,p.x+9-7,p.y-6);
  }else{
    ctx.drawImage(spr,p.x-7,p.y-6);
  }
}
function drawEnemies(){
  for(const e of G.enemies){
    if(e.state==='wait')continue;
    ctx.drawImage(enemySprite(e),Math.round(e.x-e.typeW(e)),Math.round(e.y-6));
  }
}
function render(){
  ctx.fillStyle='#000';ctx.fillRect(0,0,W,H);
  drawStars();

  if(G.state==='attract'){drawAttract();return;}

  /* game world */
  for(const e of G.enemies){
    if(e.state==='wait')continue;
    const s=enemySprite(e);
    ctx.drawImage(s,Math.round(e.x-s.width/2),Math.round(e.y-s.height/2));
  }
  if(G.beamBoss)drawBeam(G.beamBoss);
  if(G.captive&&G.captive.state!=='gone'){
    ctx.drawImage(FIGHTER_CAP,Math.round(G.captive.x-7),Math.round(G.captive.y-6));
  }
  if(G.captiveFreed){
    ctx.drawImage(FIGHTER,Math.round(G.captiveFreed.x-7),Math.round(G.captiveFreed.y-6));
  }
  for(const s of G.pshots)ctx.drawImage(SPR_BULLET,Math.round(s.x-1),Math.round(s.y-4));
  for(const b of G.ebullets)ctx.drawImage(SPR_EBUL,Math.round(b.x-1),Math.round(b.y-2));
  drawPlayer();
  for(const x of G.explosions){
    const set=x.type==='player'?PEXPLODE:EXPLODE;
    const f=Math.min(set.length-1,Math.floor(x.t/8));
    ctx.drawImage(set[f],Math.round(x.x-6),Math.round(x.y-6));
